import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x)

def fmt_value(metric, period, value):
    if period in ("WoW", "YoY"):
        return round(to_float(value), 1)
    if metric == "revenue":
        return round(to_float(value), 2)
    if metric in ("units", "orders", "rank"):
        return round(to_float(value), 0)
    if metric == "share":
        return round(to_float(value), 1)
    return round(to_float(value), 2)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    raw = []  # list of (entity, metric, period, value, formula)

    def add(entity, metric, period, value, formula):
        if value is None:
            return
        try:
            if pd.isna(value):
                return
        except (TypeError, ValueError):
            pass
        raw.append((entity, metric, period, value, formula))

    # ---------- TOTAL facts ----------
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else np.nan
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    add("TOTAL", "revenue", "TW", total_rev_tw, "Sum of Revenue_TW across all entities")
    add("TOTAL", "revenue", "LW", total_rev_lw, "Sum of Revenue_LW across all entities")
    if not pd.isna(total_rev_ly):
        add("TOTAL", "revenue", "LY", total_rev_ly, "Sum of Revenue_LY across all entities")
    add("TOTAL", "units", "TW", total_units_tw, "Sum of Units_TW across all entities")
    add("TOTAL", "units", "LW", total_units_lw, "Sum of Units_LW across all entities")
    add("TOTAL", "orders", "TW", total_orders_tw, "Sum of Orders_TW across all entities")
    add("TOTAL", "orders", "LW", total_orders_lw, "Sum of Orders_LW across all entities")

    if total_rev_lw and total_rev_lw != 0 and not pd.isna(total_rev_lw):
        wow_total = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        add("TOTAL", "revenue", "WoW", wow_total,
            "(Sum Revenue_TW - Sum Revenue_LW) / Sum Revenue_LW * 100")

    if not pd.isna(total_rev_ly) and total_rev_ly != 0:
        yoy_total = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        add("TOTAL", "revenue", "YoY", yoy_total,
            "(Sum Revenue_TW - Sum Revenue_LY) / Sum Revenue_LY * 100")

    # ---------- Biggest movers ----------
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        top_up = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        top_down = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        add(top_up['Entity'], "revenue", "WoW", top_up['WoW_Pct'],
            "Largest WoW_Pct increase: (Revenue_TW - Revenue_LW) / Revenue_LW * 100")
        if top_down['Entity'] != top_up['Entity']:
            add(top_down['Entity'], "revenue", "WoW", top_down['WoW_Pct'],
                "Largest WoW_Pct decrease: (Revenue_TW - Revenue_LW) / Revenue_LW * 100")

    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        top_up_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        top_down_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        add(top_up_y['Entity'], "revenue", "YoY", top_up_y['YoY_Pct'],
            "Largest YoY_Pct increase: (Revenue_TW - Revenue_LY) / Revenue_LY * 100")
        if top_down_y['Entity'] != top_up_y['Entity']:
            add(top_down_y['Entity'], "revenue", "YoY", top_down_y['YoY_Pct'],
                "Largest YoY_Pct decrease: (Revenue_TW - Revenue_LY) / Revenue_LY * 100")

    # ---------- Per-entity facts, ordered by Rank ----------
    df_sorted = df.sort_values('Rank', na_position='last')
    for _, row in df_sorted.iterrows():
        ent = row['Entity']
        add(ent, "revenue", "TW", row['Revenue_TW'], f"Revenue_TW for {ent}")
        add(ent, "share", "TW", row['Share_Pct'],
            "Share_Pct column: Revenue_TW / Total Revenue_TW * 100")
        add(ent, "rank", "TW", row['Rank'], "Rank column: rank of entity by Revenue_TW")

    # ---------- Build final JSON list, capped at 25 ----------
    facts = []
    seen = set()
    for entity, metric, period, value, formula in raw:
        key = (entity, metric, period)
        if key in seen:
            continue
        seen.add(key)
        facts.append({
            "entity": str(entity),
            "metric": metric,
            "period": period,
            "value": fmt_value(metric, period, value),
            "formula": formula
        })
        if len(facts) >= 25:
            break

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
